#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    std::vector<int> getPair(int n) {
        for (int d = std::sqrt(n); d >= 1; --d) {
            if (n % d == 0) return {d, n / d};
        }
        return {1, n};
    }
    std::vector<int> closestDivisors(int num) {
        auto p1 = getPair(num + 1);
        auto p2 = getPair(num + 2);
        if (std::abs(p1[0] - p1[1]) <= std::abs(p2[0] - p2[1])) return p1;
        return p2;
    }
};

class Solution {
    private int[] getPair(int n) {
        for (int d = (int)Math.sqrt(n); d >= 1; d--) {
            if (n % d == 0) return new int[]{d, n / d};
        }
        return new int[]{1, n};
    }
    public int[] closestDivisors(int num) {
        int[] p1 = getPair(num + 1);
        int[] p2 = getPair(num + 2);
        if (Math.abs(p1[0] - p1[1]) <= Math.abs(p2[0] - p2[1])) return p1;
        return p2;
    }
}

var closestDivisors = function(num) {
    const getPair = (n) => {
        for (let d = Math.floor(Math.sqrt(n)); d >= 1; d--) {
            if (n % d === 0) return [d, Math.floor(n / d)];
        }
        return [1, n];
    };
    const p1 = getPair(num + 1);
    const p2 = getPair(num + 2);
    return Math.abs(p1[0] - p1[1]) <= Math.abs(p2[0] - p2[1]) ? p1 : p2;
};
